import { Link as AriaLink } from "react-aria-components";
import type { LinkProps as AriaLinkProps } from "react-aria-components";
import type { Ref } from "react";
import "./Link.css";

type LinkVariant = "standard" | "quiet" | "subtle";

export interface LinkProps extends Omit<AriaLinkProps, "className"> {
  /**
   * Visual variant. Standard is underlined; quiet keeps surrounding ink; subtle marks
   * sibling-page navigation with muted ink and no rule. The current page retains relative weight.
   *
   * @default "standard"
   */
  variant?: LinkVariant;
  /** Additional class (optional). sd-link is always preserved. */
  className?: string;
  /** Forwarded to the underlying <a> DOM node. */
  ref?: Ref<HTMLAnchorElement>;
}

export function Link({
  variant = "standard",
  className,
  ...props
}: LinkProps) {
  return (
    <AriaLink
      {...props}
      data-variant={variant}
      className={className ? `sd-link ${className}` : "sd-link"}
    />
  );
}

.sd-link {
  color: var(--sd-link-foreground);
  text-decoration-line: underline;
  text-decoration-thickness: var(--sd-link-decoration-thickness);
  text-underline-offset: var(--sd-link-underline-offset);
  outline: none;
  cursor: pointer;
  transition:
    color var(--sd-duration-moderate) var(--sd-easing-standard),
    text-decoration-color var(--sd-duration-moderate) var(--sd-easing-standard);
}
/* quiet = a link that keeps the surrounding text's voice: body colour, no visible rule until
   you touch it. It must NOT take the brand colour on interaction — becoming brand *is* the
   standard link, so a quiet link that turns blue on hover has stopped being quiet. */
.sd-link[data-variant="quiet"] {
  color: var(--sd-link-foreground-quiet);
  text-decoration-color: transparent;
}
/* Subtle names sibling pages without a rule. Relative current weight remains the non-colour
   cue where muted and body ink differ by less than 3:1. The consumer supplies the type role. */
.sd-link[data-variant="subtle"] {
  color: var(--sd-link-foreground-subtle);
  text-decoration-line: none;
}
.sd-link[data-variant="subtle"][data-hovered],
.sd-link[data-variant="subtle"][data-pressed] {
  color: var(--sd-link-foreground-current);
}
/* The affordance is the RULE, never the hue — so each variant stays in character: standard
   thickens its rule, quiet reveals one. Neither shifts colour, which also means neither needs
   a darker brand step (Sys has none). Pressed matches hover: an inline link has no box to tint,
   and on touch — where hover never fires — this is the only feedback there is. */
.sd-link[data-hovered],
.sd-link[data-pressed] {
  text-decoration-thickness: var(--sd-link-decoration-thickness-hover);
}
/* `current` also reveals quiet's rule. Without it the state is invisible on this variant:
   quiet's resting colour IS foreground-current, so the colour swap that marks the current
   standard link changes nothing here (SubNav renders four identical items). Peers mark the
   current item with weight + a rule, never colour alone (GOV.UK service-nav, Primer nav).
   The weight half does not wait on a Sys weight scale (`font-weight` has four rungs at Sys); what
   blocks it is a RULE, not a gap. `component-contract.md` § 7 forbids wiring
   a per-property font token per component, and `component-usage.md` § Navigating versus acting
   records that Link owns no typography ON PURPOSE, so a weight here is a partial role freeze and
   needs that rule amended first. QUEUE.md carries it.
   How `[data-current]` gets SET, since nothing in this repo sets it: React Aria emits it from
   `aria-current`, which is what `SubNav` and both `Current` stories pass, and the rendered current
   item carries `aria-current` and `data-current` together. By
   `figma-projection.md` § 6 that makes this a RAC-emitted value, so it belongs in Figma as a
   `state` value and never as an axis, and it is why `figma-axis-parity:check` asks nothing of it. */
.sd-link[data-variant="quiet"][data-hovered],
.sd-link[data-variant="quiet"][data-pressed],
.sd-link[data-variant="quiet"][data-current] {
  text-decoration-color: currentColor;
}
/* The current page carries WEIGHT as well as colour, which is what the peers above do and what the
   standard variant needed: its colour swap trades the brand hue for body text and keeps the same
   underline, so on its own it is a colour-only signal. The value is RELATIVE because no absolute
   one can be right: this weight lands on whatever role the consumer put on the element, Link owning
   none, and the brands' role ceilings differ (avocado reaches 700, and 800 on the emphasized twins,
   where blueberry and mango stop at 500 and 600), while a Cmp token has no brand axis. Measured in
   three brands at two live sites: on a SubNav item at `label-medium` every candidate reads heavier,
   but on a BlogPostGrid post title, a bare Link inside an `h3.sd-type-title-medium`, avocado's
   sibling is already 700, where semibold would render the CURRENT item at 600, lighter than its
   neighbours. `bolder` is the only value heavier in all six cells. */
.sd-link[data-current] {
  color: var(--sd-link-foreground-current);
  font-weight: var(--sd-link-font-weight-current);
}
.sd-link[data-focus-visible] {
  box-shadow: 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-state-focus-ring) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  outline: var(--sd-state-focus-ring-width) solid transparent;
  border-radius: var(--sd-link-radius);
  corner-shape: superellipse(var(--sd-radius-curve));
}
.sd-link[data-disabled] {
  opacity: var(--sd-state-disabled);
  cursor: not-allowed;
}
